message.content:
{
  "hypotheses": [
    {
      "team": "home",
      "reasons": [
        {
          "text": "손흥민이 차범근과 공동 1위인 남자 국제 득점 58골에서 한 골만 더하면 단독 기록이 되므로, 이 경기에서 득점 동기가 최상단에 있다.",
          "var_ids": ["R4"]
        },
        {
          "text": "한국은 우즈베키스탄을 상대로 역대 전적 11승 4무 1패로 크게 앞서 있어 상대 전술에 대한 적응 부담이 상대적으로 적다.",
          "var_ids": ["R5"]
        },
        {
          "text": "10월에 베네수엘라와 우즈베키스탄을 잇달아 치르는 친선 일정이라 로테이션과 실험 카드를 쓰면서도 홈에서 주도권을 잡을 여지가 있다.",
          "var_ids": ["R6"]
        },
        {
          "text": "9월 두 경기에서 1-1 결과를 냈다는 점은 득점력과 실점이 함께 흔들렸다는 뜻이므로, 홈에서 공격 템포를 끌어올리는 방향으로 되돌릴 수 있다.",
          "var_ids": ["R7"]
        }
      ],
      "breaks": [
        {
          "text": "김민재가 최근 경기 피로로 우즈베키스탄전에 나서기 어려우면 중앙 수비의 기준점이 사라진다.",
          "var_ids": ["R1", "R2"]
        },
        {
          "text": "김민재 대신 김태현이 이한범과 함께 센터백으로 출전하는 조합은 호흡이 검증되지 않아 배후 공간 관리가 흔들릴 수 있다.",
          "var_ids": ["R3"]
        },
        {
          "text": "9월에 에콰도르를 3-0으로 이겼다가 우루과이에 1-4로 크게 진 것처럼 결과 편차가 크다는 점은 경기 운영이 한쪽으로 기울면 통제를 잃을 수 있음을 보여준다.",
          "var_ids": ["R7"]
        }
      ]
    },
    {
      "team": "away",
      "reasons": [
        {
          "text": "김민재가 최근 경기 피로와 이틀 연속 훈련 불참으로 결장 가능성이 높아, 한국의 중앙 수비 강도가 떨어진 상태를 공략할 수 있다.",
          "var_ids": ["R1", "R2"]
        },
        {
          "text": "한국이 김태현과 이한범의 새 센터백 조합을 세워야 하는 상황이면 조직적인 수비 정렬이 완성되기 전에 침투와 세컨드 볼로 기회를 만들 수 있다.",
          "var_ids": ["R3"]
        },
        {
          "text": "한국이 9월에 우루과이전에서 1-4로 무너진 사례가 있듯 실점이 한 번 나오면 흐름이 급격히 기우는 구간이 있어, 선제 실점을 유도하면 경기를 뒤집을 발판이 생긴다.",
          "var_ids": ["R7"]
        }
      ],
      "breaks": [
        {
          "text": "손흥민이 득점 기록을 향해 적극적으로 슈팅을 가져가면 한국의 공격이 먼저 열리면서 수비 계획이 흔들린다.",
          "var_ids": ["R4"]
        },
        {
          "text": "한국이 우즈베키스탄전에서 역사적으로 크게 앞선 전적을 갖고 있어, 경기 초반 주도권을 내주면 추격 구도로 몰린다.",
          "var_ids": ["R5"]
        },
        {
          "text": "한국이 10월 두 차례 친선 경기를 준비하며 홈에서 전력을 실험할 여유가 있다는 점은 상대가 주도권을 되찾기 어렵게 만든다.",
          "var_ids": ["R6"]
        }
      ]
    }
  ],
  "scenarios": [
    {
      "id": "S1",
      "outcomes": [[3, 2], [4, 2]],
      "driver_vars": ["R4", "R1", "R2", "R3"],
      "mechanism": "손흥민이 기록을 향해 적극적으로 슈팅을 시도하며 한국이 전방에서 볼을 오래 잡고, 김민재 결장으로 정렬이 늦어진 중앙 수비가 역습 한 번에 배후를 내주는 구도가 겹친다. 양쪽 모두 득점이 열린 채 경기가 길게 늘어진다."
    },
    {
      "id": "S2",
      "outcomes": [[2, 1], [3, 1]],
      "driver_vars": ["R5", "R6", "R1", "R3"],
      "mechanism": "한국이 상대 전적에서 앞선다는 자신감과 홈 친선 일정의 여유를 바탕으로 점유와 공격 지역 점유를 가져가 득점을 쌓는다. 다만 새 센터백 조합의 호흡 문제로 한 번은 실점을 허용한다."
    },
    {
      "id": "S3",
      "outcomes": [[2, 0], [3, 0]],
      "driver_vars": ["R4", "R5", "R6"],
      "mechanism": "손흥민의 득점 동기와 홈에서의 주도권이 결합해 한국이 이른 시간에 앞서 나가고, 상대가 볼을 가지러 나온 뒤 공간이 벌어지며 추가 득점이 따라붙는다. 수비 쪽 격차가 결과로 이어져 실점 없이 마무리된다."
    },
    {
      "id": "S4",
      "outcomes": [[1, 2], [0, 1]],
      "driver_vars": ["R1", "R2", "R3", "R7"],
      "mechanism": "김민재가 빠진 한국의 중앙 수비가 새 조합으로 버티지 못하고, 9월 우루과이전처럼 실점 이후 흐름이 한쪽으로 기우는 구간이 재현된다. 우즈베키스탄이 그 틈을 통해 역전 또는 리드를 가져간다."
    },
    {
      "id": "S5",
      "outcomes": [[1, 1], [0, 0]],
      "driver_vars": ["R7", "R3", "R6"],
      "mechanism": "9월에 1-1 결과가 반복됐듯 한국의 공격 마무리 효율이 떨어지고, 새 센터백 조합이 깊게 내려서며 실점 위험을 줄이는 방향으로 경기가 잠긴다. 서로 결정적 장면을 살리지 못한 채 득점이 적게 남는다."
    }
  ]
}
